  if(s->maul_proc[source]){int life=ticks(g,source,DOTA_ITEM_GIANT_MAUL,IP_DEBUFF_DURATION);s->maul_proc[source]=0;s->cooldown[source][CD_MAUL]=(uint16_t)cooldown(DOTA_ITEM_GIANT_MAUL);dota_items_apply_effect(g,source,target,IE_SLOW,life,par(g,source,DOTA_ITEM_GIANT_MAUL,IP_MOVESPEED_SLOW),DOTA_ITEM_GIANT_MAUL);dota_items_apply_effect(g,source,target,IE_AS,life,-par(g,source,DOTA_ITEM_GIANT_MAUL,IP_ATTACK_SLOW),DOTA_ITEM_GIANT_MAUL);cast_slow(g,source,target,life,par(g,source,DOTA_ITEM_GIANT_MAUL,IP_CAST_SLOW));}
