static void launch_rattle(DotaGame*g,int h){int n,i,j,choice,used[2]={-1,-1},radius=par(g,h,DOTA_ITEM_RATTLECAGE,IP_RADIUS);for(n=0;n<min_i(2,par(g,h,DOTA_ITEM_RATTLECAGE,IP_TARGET_COUNT));n++){int best=0x7fffffff;choice=-1;for(i=0;i<DOTA_MAX_UNITS;i++)if(live(g,i)&&g->units[i].team!=g->units[h].team&&!dota_unit_invulnerable(g,i)&&dota_unit_visible(g,h,i)&&source_range(&g->units[h],&g->units[i],radius)){int dx=g->units[h].x-g->units[i].x,dy=g->units[h].y-g->units[i].y,score=dx*dx+dy*dy;if(g->units[i].type!=DOTA_HERO)score+=DOTA_WORLD*DOTA_WORLD;for(j=0;j<n;j++)if(used[j]==i)break;if(j<n)continue;if(score<best){best=score;choice=i;}}if(choice>=0){DotaItemSpecialEvent*e=event_slot(g,SP_BOLT,h,choice,DOTA_ITEM_RATTLECAGE);if(!e)continue;used[n]=choice;e->x_q16=g->units[h].x*DOTA_MOVE_ONE;e->y_q16=g->units[h].y*DOTA_MOVE_ONE;e->amount=par(g,h,DOTA_ITEM_RATTLECAGE,IP_PROJECTILE_DAMAGE);e->due=g->tick+1;e->expires=g->tick+8*DOTA_HZ;}}}
