 if(hero(g,target)&&has(g,target,DOTA_ITEM_RATTLECAGE)){if(g->tick-s->rattle_last[target]>ticks(g,target,DOTA_ITEM_RATTLECAGE,IP_DAMAGE_RESET_INTERVAL))s->rattle_damage[target]=0;s->rattle_last[target]=g->tick;s->rattle_damage[target]+=dealt;threshold=par(g,target,DOTA_ITEM_RATTLECAGE,IP_DAMAGE_THRESHOLD);while(threshold>0&&s->rattle_damage[target]>=threshold){s->rattle_damage[target]-=threshold;launch_rattle(g,target);}}
