  if(e->kind==SP_MANA_REFUND){part=(e->amount+e->pulses-1)/e->pulses;e->amount-=part;dota_items_restore(g,src,target,0,part);e->due+=e->remaining;}
  else if(e->kind==SP_DEBT){part=(e->amount+e->pulses-1)/e->pulses;e->amount-=part;dota_rules_item_damage(g,src,target,part,4);dota_items_special_after_damage(g,src,target,part,4);e->due+=e->remaining;}
  else {int piece=e->amount/e->pulses;e->amount-=piece;e->remaining+=piece;part=e->remaining/100;e->remaining%=100;if(part>0)special_damage(g,src,target,part,1);j=src>=0?ticks(g,src,DOTA_ITEM_SEARING_SIGNET,IP_BURN_TICKRATE):raw(DOTA_ITEM_SEARING_SIGNET,IP_BURN_TICKRATE)/5;e->due+=max_i(1,j);}
  if(e->pulses){e->pulses--;}if(!e->pulses)e->kind=0;
